	return async (url) => {
		let robots = cache.get(url.origin);
		if (!robots) {
			robots = load(url.origin);
			cache.set(url.origin, robots);
		}
		return (await robots)?.isAllowed(url.href, USER_AGENT) !== false;
	};
}

